#!/bin/bash
# shellcheck disable=all
set -euo pipefail
jeb() {
    code="$(grep -m 1 -B 999 -A 1 "^jeb " < "$0")"
    echo -n "${code}"$'\n\n\n\n'"$(cargo run --release --bin jeb -- "$@")"$'\n' > "$0"
    exit
}



